#!/usr/bin/env node
/**
 * Build script that generates src/worker-bundle.ts
 *
 * Reads dist/view/index.html and writes it as an exported constant
 * so standalone runtimes and workers can serve it without disk I/O.
 */

import { readFile, writeFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const VIEW_HTML_PATH = join(ROOT, "dist", "view", "index.html");
const OUTPUT_PATH = join(ROOT, "src", "worker-bundle.ts");

async function main() {
  console.log("Reading dist/view/index.html...");
  let viewHtml;
  try {
    viewHtml = await readFile(VIEW_HTML_PATH, "utf-8");
    console.log(`  View HTML: ${(viewHtml.length / 1024).toFixed(1)} KB`);
  } catch {
    console.warn("  dist/view/index.html não encontrado. Usando placeholder padrão.");
    viewHtml = `<!DOCTYPE html><html><body><div id="root"></div></body></html>`;
  }

  const output = `// AUTO-GENERATED by scripts/build-worker-bundle.mjs — DO NOT EDIT
// Generated at: ${new Date().toISOString()}

export const WIDGET_HTML: string = ${JSON.stringify(viewHtml)};
`;

  await writeFile(OUTPUT_PATH, output, "utf-8");
  const outputKb = (Buffer.byteLength(output) / 1024).toFixed(1);
  console.log(`Wrote ${OUTPUT_PATH} (${outputKb} KB)`);
  console.log("Done!");
}

main().catch((err) => {
  console.error("Build failed:", err);
  process.exit(1);
});
